#!/usr/bin/env node
/**
 * Keeps the apps' API and business logic identical to the websites'.
 * Generates from the web's single source (never edit the generated files):
 *
 *   shared/src/services/endpoints.js  →  packages/core/api/endpoints.generated.js
 *   shared/src/services/api.js        →  packages/core/api/hooks.ts  (hook names)
 *   LOGIC below                       →  packages/core/shared/*.js   (pure logic)
 *
 * After changing any of those in shared/: npm run sync:api (from mobile/)
 * CI runs npm run check:api and fails if anything is out of date.
 */
const fs = require('fs');
const path = require('path');

const sharedSrc = path.resolve(__dirname, '../../shared/src');
const core = path.resolve(__dirname, '../packages/core');
const BANNER = (from) => `/**
 * GENERATED by mobile/tools/sync-api-hooks.js from shared/src/${from}.
 * Do not edit: change the shared file, then run \`npm run sync:api\` from mobile/.
 */
/* eslint-disable */
`;

/**
 * Web logic the apps share, platform-free. `imports` maps each import the file
 * makes to its app path; an import not listed fails the sync, so a browser-only
 * dependency can never slip into the apps.
 */
const LOGIC = [
  { from: 'utils/money.js', to: 'shared/money.js', imports: {} },
  { from: 'utils/doorAddress.js', to: 'shared/doorAddress.js', imports: {} },
  { from: 'utils/slots.js', to: 'shared/slots.js', imports: {} },
  { from: 'utils/distance.js', to: 'shared/distance.js', imports: {} },
  { from: 'components/jobs/jobOffers.js', to: 'shared/jobOffers.js', imports: {} },
  { from: 'provider/workerHome.js', to: 'shared/workerHome.js', imports: {} },
  { from: 'provider/workerNotifications.js', to: 'shared/workerNotifications.js', imports: {} },
  { from: 'provider/jobFlows.js', to: 'shared/jobFlows.js', imports: { '../utils/money': './money' } },
  { from: 'components/home/problemArt.js', to: 'shared/problemArt.js', imports: {} },
  { from: 'components/home/serviceArt.js', to: 'shared/serviceArt.js', imports: { './problemArt': './problemArt' } },
  { from: 'components/provider/weeklyHoursRules.js', to: 'shared/weeklyHoursRules.js', imports: {} },
  { from: 'components/account/passwordRules.js', to: 'shared/passwordRules.js', imports: {} },
  { from: 'config/releases.js', to: 'shared/releases.js', imports: {} },
  { from: 'config/appVersion.js', to: 'shared/appVersion.js', imports: {} },
  { from: 'i18n/translations.js', to: 'shared/translations.js', imports: {} },
  { from: 'components/events/eventPhotos.js', to: 'shared/eventPhotos.js', imports: {} },
  { from: 'customer/useMyJobs.js', to: 'shared/useMyJobs.js', imports: { react: 'react', '../services/api': '../api/hooks', '../i18n/translations': './translations' } },
  { from: 'constants/services.js', to: 'shared/services.js', imports: {} },
  { from: 'customer/schedule.js', to: 'shared/schedule.js', imports: {} },
  { from: 'customer/jobKinds.js', to: 'shared/jobKinds.js', imports: { '../provider/jobFlows': './jobFlows' } },
  { from: 'customer/trackingSteps.js', to: 'shared/trackingSteps.js', imports: {} },
  { from: 'provider/useProviderJobs.js', to: 'shared/useProviderJobs.js', imports: { react: 'react', '../services/api': '../api/hooks' } },
];

const files = [];

// 1. The call list, copied as-is.
files.push([path.join(core, 'api/endpoints.generated.js'),
  BANNER('services/endpoints.js') + fs.readFileSync(path.join(sharedSrc, 'services/endpoints.js'), 'utf8')]);

// 2. The hook names, bound to the apps' API.
const apiSrc = fs.readFileSync(path.join(sharedSrc, 'services/api.js'), 'utf8');
const block = apiSrc.slice(apiSrc.indexOf('export const {'), apiSrc.indexOf('} = api;'));
const names = [...new Set([...block.matchAll(/\b(use[A-Z]\w*)\b/g)].map((m) => m[1]))];
if (names.length < 100) throw new Error(`Only ${names.length} hooks found in api.js; did the export block move?`);
files.push([path.join(core, 'api/hooks.ts'), `${BANNER('services/api.js')}import { api } from './sharedApi';

// The call list is plain JavaScript, so its hooks are untyped here.
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const h = api as unknown as Record<string, any>;

${names.map((n) => `export const ${n} = h.${n};`).join('\n')}
`]);

// 3. Shared logic, imports rewritten.
for (const { from, to, imports } of LOGIC) {
  let src = fs.readFileSync(path.join(sharedSrc, from), 'utf8');
  src = src.replace(/(from\s+|import\s+)(['"])([^'"]+)\2/g, (all, pre, q, spec) => {
    if (!(spec in imports)) throw new Error(`${from} imports '${spec}', which the apps can't load. Map it in LOGIC or keep the file platform-free.`);
    return `${pre}${q}${imports[spec]}${q}`;
  });
  files.push([path.join(core, to), BANNER(from) + src]);
}

if (process.argv.includes('--check')) {
  const stale = files.filter(([f, text]) => !fs.existsSync(f) || fs.readFileSync(f, 'utf8') !== text);
  if (stale.length) {
    console.error(`Out of date: ${stale.map(([f]) => path.relative(core, f)).join(', ')}. Run: npm run sync:api`);
    process.exit(1);
  }
  console.log(`In sync with the websites: ${names.length} hooks, ${LOGIC.length} logic files.`);
} else {
  for (const [f, text] of files) {
    fs.mkdirSync(path.dirname(f), { recursive: true });
    fs.writeFileSync(f, text);
  }
  console.log(`Synced ${names.length} hooks, the call list and ${LOGIC.length} logic files from shared/src.`);
}
